/* scripts/opening-balances14234.js */
/* Opening setup is guarded by the database, never by a zero-balance guess. */
(()=>{'use strict';const $=id=>document.getElementById(id),esc=v=>escapeHtml(String(v??''));let status=null,checking=false,overlay=null;
const key=()=> 'ojm_opening14234:'+String(OJM_SUPABASE_URL)+':'+liveProfile?.id;
async function check(){if(checking||!liveProfile||liveProfile.role!=='admin')return;checking=true;const who=liveProfile.id;try{const r=await ojmDb.rpc('opening_status14234');if(liveProfile?.id!==who)return;status=r.error?null:r.data;const pending=localStorage.getItem(key());$('openingBalances14234').hidden=!(status?.available||pending);if(r.error&&JournalModule.entries.length===0){$('openingBalances14234').hidden=false;status={install:true}}}finally{checking=false}}
async function open(){await check();if(!status)return;if(status.install){showCenterStatus('Install setup/INSTALL-OPENING-BALANCES-v142.34.sql once, then reopen Chart of Accounts.',true);return}
 let job;try{job=JSON.parse(localStorage.getItem(key())||'null')}catch{}
 if(job&&job.generation!==status.generation){localStorage.removeItem(key());job=null}if(!status.available&&!job)return;
 overlay=document.createElement('div');overlay.className='save-overlay14234';const box=document.createElement('form');box.className='save-panel14234';box.style.width='min(960px,100%)';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label','Opening Balances');
 const accounts=AccountingStore.accounts.filter(a=>a.isPosting!==false&&a.active!==false&&a.currency!=='NA');
 box.innerHTML='<header><h2>Opening Balances</h2><button type="button" data-close>×</button></header><p>Enter your starting balances. Debit and credit totals must match within each currency. Finalizing closes this setup.</p><label>Opening date <input name="date" type="date" required value="'+new Date().toISOString().slice(0,10)+'"></label><div class="opening-scroll14234"><table class="opening-table14234"><thead><tr><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody>'+accounts.map(a=>'<tr data-account="'+esc(a.id)+'"><td>'+esc(currencySymbolV6(a.currency)+' '+a.code+' — '+a.name)+'</td><td><input aria-label="Debit '+esc(a.name)+'" inputmode="decimal" data-dr></td><td><input aria-label="Credit '+esc(a.name)+'" inputmode="decimal" data-cr></td></tr>').join('')+'</tbody></table></div><p role="status"></p><button type="submit">Finalize Opening Balances</button>';
 overlay.append(box);document.body.append(overlay);box.querySelector('[data-close]').onclick=()=>{overlay.remove();overlay=null};
 if(job){box.elements.date.value=job.entries[0].p_transaction_date;for(const l of job.entries[0].p_lines){const row=box.querySelector('[data-account="'+CSS.escape(l.account_id)+'"]');if(row){row.querySelector('[data-dr]').value=l.debit||'';row.querySelector('[data-cr]').value=l.credit||''}}box.querySelectorAll('input').forEach(n=>n.disabled=true);box.querySelector('[type=submit]').textContent='Retry Opening Balances'}
 box.onsubmit=async e=>{e.preventDefault();const btn=box.querySelector('[type=submit]'),message=box.querySelector('[role=status]');if(btn.disabled)return;btn.disabled=true;const who=liveProfile?.id,storageKey=key();try{if(!job){const lines=[];const sums={};for(const row of box.querySelectorAll('[data-account]')){const a=accounts.find(a=>a.id===row.dataset.account),debit=parseAppNumber(row.querySelector('[data-dr]').value||0),credit=parseAppNumber(row.querySelector('[data-cr]').value||0);if(!Number.isFinite(debit)||!Number.isFinite(credit)||debit<0||credit<0||(debit&&credit))throw Error('Use one nonnegative debit or credit per account.');if(!debit&&!credit)continue;sums[a.currency]=(sums[a.currency]||0)+Math.round(debit*100)-Math.round(credit*100);lines.push({account_id:a.id,description:'Opening Balances',currency_code:a.currency,debit,credit})}if(lines.length<2||Object.values(sums).some(n=>n!==0))throw Error('Balance debits and credits in each currency before finalizing.');job={generation:status.generation,id:'opening-'+crypto.randomUUID(),entries:[{p_transaction_date:box.elements.date.value,p_memo:'Opening Balances',p_lines:lines,p_prefix:ApplicationSettings.accounting?.journalPrefix||'OJM',p_digits:Number(ApplicationSettings.accounting?.journalDigits)||6}]};localStorage.setItem(storageKey,JSON.stringify(job));box.querySelectorAll('input').forEach(n=>n.disabled=true)}
 const r=await ojmDb.rpc('post_opening_balances14234',{p_generation:job.generation,p_request_key:job.id,p_entries:job.entries});if(r.error)throw r.error;if(!Array.isArray(r.data)||!r.data[0]?.entry_id)throw Error('Save receipt not confirmed. Retry with this same reference.');localStorage.removeItem(storageKey);if(liveProfile?.id!==who)return;overlay?.remove();overlay=null;await loadJournalFromSupabase();await check();}catch(err){message.textContent=err.message;btn.textContent=job?'Retry Opening Balances':'Finalize Opening Balances'}finally{btn.disabled=false}};
}
function ready(){$('openingBalances14234').onclick=open;const scroll=window.scrollToAccountModule;window.scrollToAccountModule=function(id,...args){const r=scroll.call(this,id,...args);if(id==='sec-chart-accounts')check();return r};window.addEventListener('page113',()=>{if($('sec-chart-accounts')?.getClientRects().length)check()})}ready();window.openingBalances14234={check,open};
})();

